    case 3, 4, 5: expected = ["version", "pageId", "rainbow", "strokes"]
    case 6: expected = ["version", "paper", "pageId", "rainbow", "strokes"]
    case 7: expected = ["version", "paper", "pageId", "rainbow", "seedCursor", "commands"]
