      let paper = try object(value["paper"])
      if try string(paper, "kind") == "unadopted" { try keys(paper, ["kind"]); try checked(count == 0) }
      else {
        try keys(paper, ["kind", "cssWidth", "cssHeight", "backingScale"])
        try checked(string(paper, "kind") == "adopted")
